"""Jinja2 template for the generated Manim scene script."""
from __future__ import annotations

from jinja2 import Template

SCENE_CLASS_NAME = "MasScene"

# The construct body is pre-rendered (already indented 8 spaces) and injected.
_TEMPLATE = Template(
    '''# AUTO-GENERATED by Math Animation Studio. Do not edit by hand.
from manim import *
import numpy as np
from numpy import sin, cos, tan, exp, log, sqrt, pi, e


class {{ class_name }}(Scene):
    def construct(self):
        self.camera.background_color = "{{ background_color }}"
{{ body }}
''',
    keep_trailing_newline=True,
)


def render_script(body: str, background_color: str = "#000000") -> str:
    return _TEMPLATE.render(
        class_name=SCENE_CLASS_NAME,
        background_color=background_color,
        body=body,
    )
